assert len(W)==len({w['word'] for w in W})
assert all(len(w['examples'])>=2 and all(len(e)==2 and all(e) for e in w['examples']) for w in W)
assert all(isinstance(r['exclude'],dict) for r in roots)
assert all(w['history'] and all(len(h)==2 and all(h) for h in w['history']) for w in W)
assert all(all(w.get(k) for k in ['ipa','meaning','sense','split','explanation','usage','contrast','sources']) for w in W)
